mapper.insert:
INSERT INTO docs_distribution_account_request_nonce (
    client_id, nonce, received_at
) VALUES (
    #{clientId}, CAST(#{nonce} AS uuid), CURRENT_TIMESTAMP
)
ON CONFLICT DO NOTHING

mapper.select:
SELECT 
  FROM docs_distribution_account_request
 WHERE source_system_id = #{sourceSystemId}
   AND correlation_id = #{correlationId}

SELECT 
  FROM docs_distribution_account_request
 WHERE client_id = #{clientId}
   AND source_system_id = #{sourceSystemId}
   AND event_id = CAST(#{eventId} AS uuid)

SELECT FROM docs_distribution_account_request WHERE 1 = 1
AND status = #{status}
AND request_type = #{requestType}
AND source_system_id ILIKE '%' || #{sourceSystemId} || '%'
AND ( correlation_id ILIKE '%' || #{keyword} || '%' OR representative_id ILIKE '%' || #{keyword} || '%' OR representative_name ILIKE '%' || #{keyword} || '%' OR representative_email ILIKE '%' || #{keyword} || '%' OR target_user_id ILIKE '%' || #{keyword} || '%' OR target_user_name ILIKE '%' || #{keyword} || '%' OR target_user_email ILIKE '%' || #{keyword} || '%' OR COALESCE(organization_name, '') ILIKE '%' || #{keyword} || '%' )
ORDER BY CASE status WHEN 'PENDING' THEN 0 ELSE 1 END, received_at DESC, request_id DESC LIMIT #{limit} OFFSET #{offset}
